        assert_eq!(sky.settings.fade_bottom, RgbColor::new(10, 20, 30));
        assert_eq!(sky.settings.modulation, Some(0x20ff_80ff));
        assert_eq!(sky.settings.back_color_raw, 0x003f_42c8);
